//! Declares the `AppManifest`. With it, Tauri checks app commands against the capabilities too:
//! a command is denied until a capability grants it. The list is the commands of
//! `src/commands.rs` (its `COMMANDS`, which a test checks against this file); tauri-build
//! writes an `allow-<command>` permission for each into `permissions/autogenerated/`, and
//! `capabilities/main.json` grants each one by name (`capabilities/settings.json` a subset), but
//! `count_ui`, which `capabilities/counts.json` grants `main` on its own.
//!
//! The `e2e` build adds `E2E`'s commands, granted by `capabilities/e2e.json`, and the `marks`
//! build `MARKS`'s too, granted by `capabilities/marks.json` (`src/e2e.rs` adds those files at
//! setup in those builds only). tauri-build never removes a permission file it wrote, so a
//! build without a feature removes that feature's from `permissions/autogenerated/`: the default
//! build then defines exactly the permissions of its sixteen commands, as before the features.
//!
//! On Windows (MSVC), the linker embeds `windows-app.manifest` (Common Controls 6, which
//! tauri-plugin-dialog's `TaskDialogIndirect` needs, and the supported Windows versions, which the
//! room's layered child window over its maximise button needs) into every binary this crate
//! links, the lib's unit-test binary included. tauri-build would embed its manifest into the app
//! only (`rustc-link-arg-bins`), and the test binary then fails to start with 0xc0000139
//! (tauri-apps/tauri#13419); `rustc-link-arg-tests` does not reach lib unit tests.
//!
//! `CLAUSEO_RELEASE_DATE`, which `.github/workflows/release.yml` sets for a tagged release and
//! `src/commands.rs` reads with `option_env!`, must be a `YYYY-MM-DD` date when set; any other
//! value fails the build. Unset (dev and CI builds), there is no release date.

use std::io::Write as _;

/// The default build's commands: `COMMANDS` in `src/commands.rs`.
const RELEASE: &[&str] = &[
    "dispatch",
    "query",
    "open_stream",
    "subscribe",
    "unsubscribe",
    "subscribe_app",
    "ack",
    "answer_permission",
    "pick_folder",
    "display_info",
    "open_external",
    "open_file",
    "reveal",
    "open_settings",
    "count_ui",
    "setup",
];

/// What the `e2e` build adds: `E2E_COMMANDS` in `src/commands.rs`.
const E2E: &[&str] = &["perf_channel_bytes"];

/// What the `marks` build adds to `e2e`'s: `MARKS_COMMANDS` in `src/commands.rs`.
const MARKS: &[&str] = &["marks_memory", "marks_finish"];

/// The commands of this build, and the feature commands it does not have.
fn commands(e2e: bool, marks: bool) -> (Vec<&'static str>, Vec<&'static str>) {
    let mut ours = RELEASE.to_vec();
    let mut absent = Vec::new();
    for (on, extra) in [(e2e, E2E), (marks, MARKS)] {
        if on {
            ours.extend_from_slice(extra);
        } else {
            absent.extend_from_slice(extra);
        }
    }
    (ours, absent)
}

/// Removes the permission files tauri-build wrote for `absent` in a build that had them.
#[expect(
    clippy::disallowed_methods,
    reason = "build script: removes tauri-build's own generated files for commands not built"
)]
fn remove_permissions(dir: &str, absent: &[&str]) -> std::io::Result<()> {
    let generated = std::path::Path::new(dir).join("permissions/autogenerated");
    for command in absent {
        let file = generated.join(format!("{command}.toml"));
        if file.exists() {
            std::fs::remove_file(file)?;
        }
    }
    Ok(())
}

/// The variable release.yml sets to the tag's date, UTC.
const RELEASE_DATE: &str = "CLAUSEO_RELEASE_DATE";

/// True when `date` is `YYYY-MM-DD` with a month from 01 to 12 and a day from 01 to 31.
fn is_release_date(date: &str) -> bool {
    let bytes = date.as_bytes();
    let digits = |range: std::ops::Range<usize>| {
        bytes
            .get(range)
            .is_some_and(|part| part.iter().all(u8::is_ascii_digit))
    };
    let number = |range: std::ops::Range<usize>| date.get(range).and_then(|n| n.parse::<u8>().ok());
    bytes.len() == 10
        && digits(0..4)
        && bytes.get(4) == Some(&b'-')
        && digits(5..7)
        && bytes.get(7) == Some(&b'-')
        && digits(8..10)
        && number(5..7).is_some_and(|month| (1..=12).contains(&month))
        && number(8..10).is_some_and(|day| (1..=31).contains(&day))
}

/// Fails on a release date that is set but not `YYYY-MM-DD`, and reruns when it changes.
fn check_release_date() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    writeln!(
        std::io::stdout().lock(),
        "cargo:rerun-if-env-changed={RELEASE_DATE}"
    )?;
    match std::env::var(RELEASE_DATE) {
        Err(std::env::VarError::NotPresent) => Ok(()),
        Ok(date) if is_release_date(&date) => Ok(()),
        Ok(date) => Err(format!("{RELEASE_DATE} is {date:?}, not a YYYY-MM-DD date").into()),
        Err(error) => Err(format!("{RELEASE_DATE} is not valid Unicode: {error}").into()),
    }
}

fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    check_release_date()?;
    let e2e = std::env::var_os("CARGO_FEATURE_E2E").is_some();
    let marks = std::env::var_os("CARGO_FEATURE_MARKS").is_some();
    let (ours, absent) = commands(e2e, marks);
    remove_permissions(&std::env::var("CARGO_MANIFEST_DIR")?, &absent)?;
    // tauri-build keeps the list for the build script's life, which this is.
    let ours: &'static [&'static str] = Box::leak(ours.into_boxed_slice());
    let mut windows = tauri_build::WindowsAttributes::new();
    if std::env::var("CARGO_CFG_TARGET_ENV").is_ok_and(|env| env == "msvc") {
        windows = tauri_build::WindowsAttributes::new_without_app_manifest();
        let dir = std::env::var("CARGO_MANIFEST_DIR")?;
        let manifest = std::path::Path::new(&dir).join("windows-app.manifest");
        let mut out = std::io::stdout().lock();
        writeln!(out, "cargo:rerun-if-changed={}", manifest.display())?;
        writeln!(out, "cargo:rustc-link-arg=/MANIFEST:EMBED")?;
        writeln!(
            out,
            "cargo:rustc-link-arg=/MANIFESTINPUT:{}",
            manifest.display()
        )?;
    }
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .windows_attributes(windows)
            .app_manifest(tauri_build::AppManifest::new().commands(ours)),
    )?;
    Ok(())
}
